// 一个 Voice orb 只呈现一个状态；把多个实例并排即可同时展示会话状态。
var listening = new ArcVoiceOrb
{
    Width = 540,
    Height = 470,
    State = ArcVoiceOrbState.Listening,
    Elapsed = 12,
    Transcript = "The studio opens at nine. Shall I book a table for two?"
};

var thinking = new ArcVoiceOrb { State = ArcVoiceOrbState.Thinking, Transcript = "Checking the calendar…" };
var speaking = new ArcVoiceOrb { State = ArcVoiceOrbState.Speaking, Elapsed = 21 };
var muted = new ArcVoiceOrb { State = ArcVoiceOrbState.Listening, Muted = true, Elapsed = 34 };
